// ===== 06 VDR — Build vendor reports =====
// Input: the latest "Reece Vendor Disposition Feed" email (LP report 135 Lead Disposition Detail 2,
// all dispositions, entry date last 90 days). Output: one item per due vendor with a CSV, or a
// blocked/empty status. Nothing is sent from here. FAILS CLOSED on any doubt about the feed.
const INTERNAL_TO = 'm.richard@reecewindows.com';
const FEED_MAX_AGE_HOURS = 26;      // feed must have arrived within this window
const MIN_SIZE_VS_LAST = 0.7;       // block if feed has < 70% of the rows of the last good feed
const TZ = 'America/New_York';

// Output columns: [header vendors see, LP column name(s)]. Sale amount shown on purpose (Mark, 2026-10-13).
const OUT_COLS = [
  ['Lead ID', ['id']], ['Entry Date', ['entrydate']], ['First Name', ['FirstName']],
  ['Last Name', ['lastname']], ['Phone', ['Phone']], ['Email', ['Email']],
  ['Address', ['Address1']], ['City', ['city']], ['State', ['state']], ['Zip', ['Zip']],
  ['Source', ['SourceSubDescr']], ['Disposition', ['dspdescr']], ['Last Result', ['lastresult']],
  ['Appointment Date', ['ApptDate']], ['Job Status', ['JobStatus']], ['Sale Amount', ['GSA']],
];
const REQUIRED = ['id', 'entrydate', 'SourceSubDescr', 'dspdescr', 'Category', 'SDate'];

function parseCSV(text) {
  const rows = []; let row = [], field = '', q = false;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (q) {
      if (c === '"') { if (text[i + 1] === '"') { field += '"'; i++; } else q = false; }
      else field += c;
    } else if (c === '"') q = true;
    else if (c === ',') { row.push(field); field = ''; }
    else if (c === '\n') { row.push(field); rows.push(row); row = []; field = ''; }
    else if (c === '\r') { }
    else field += c;
  }
  if (field !== '' || row.length) { row.push(field); rows.push(row); }
  return rows.filter(r => r.some(v => String(v).trim() !== ''));
}
function toCSV(rows) {
  return rows.map(r => r.map(v => { v = String(v ?? ''); return /[",\n\r]/.test(v) ? '"' + v.replace(/"/g, '""') + '"' : v; }).join(',')).join('\r\n') + '\r\n';
}
// Returns 'YYYY-MM-DD' or null. Accepts M/D/YYYY (with optional time) and YYYY-MM-DD.
function ymd(v) {
  const s = String(v ?? '').trim();
  let m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
  if (m) return `${m[1]}-${m[2].padStart(2, '0')}-${m[3].padStart(2, '0')}`;
  m = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{2,4})/);
  if (m) { const y = m[3].length === 2 ? '20' + m[3] : m[3]; return `${y}-${m[1].padStart(2, '0')}-${m[2].padStart(2, '0')}`; }
  return null;
}
const norm = s => String(s ?? '').trim().replace(/\s+/g, ' ').toLowerCase();
const localDate = d => d.toLocaleDateString('en-CA', { timeZone: TZ });
function addDays(dateStr, n) { const d = new Date(dateStr + 'T12:00:00Z'); d.setUTCDate(d.getUTCDate() + n); return d.toISOString().slice(0, 10); }

const cfg = $('Get due vendors').first().json;
const due = Array.isArray(cfg.due) ? cfg.due : [];
const mapped = new Set((cfg.mapped_sub_sources || []).map(norm));
const prevRows = cfg.prev_source_rows ?? null;
const now = new Date();
const today = localDate(now);

// ---------- 1. Load and check the feed (applies to every vendor) ----------
let feed = { ok: false, reason: 'no_feed_email' };
const mail = $input.all();
for (let i = 0; i < mail.length && !feed.ok; i++) {
  const it = mail[i]; const bin = it.binary ?? {};
  if (!it.json || !it.json.id) continue;
  const receivedMs = Number(it.json.internalDate) || Date.parse(it.json.date || '');
  const key = Object.keys(bin).find(k => /\.csv$/i.test(bin[k]?.fileName ?? ''));
  if (!key) { feed = { ok: false, reason: 'no_csv_attachment' }; continue; }
  const buf = await this.helpers.getBinaryDataBuffer(i, key);
  feed = { ok: true, file: bin[key].fileName, text: buf.toString('utf8').replace(/^﻿/, ''),
           received_at: Number.isFinite(receivedMs) ? new Date(receivedMs).toISOString() : null, receivedMs };
}
let header = [], data = [], col = {}, feedRows = 0, windowStart = null;
if (feed.ok) {
  const rows = parseCSV(feed.text);
  const h = rows.findIndex((r, idx) => idx < 10 && r.some(c => String(c).trim() === 'SourceSubDescr'));
  if (h === -1) feed = { ...feed, ok: false, reason: 'header_not_found' };
  else {
    header = rows[h].map(c => String(c).trim());
    const lower = header.map(c => c.toLowerCase());
    for (const name of new Set([...REQUIRED, ...OUT_COLS.flatMap(c => c[1]), 'ApptDate'])) {
      col[name] = lower.indexOf(name.toLowerCase());   // case-insensitive (City vs city layouts)
    }
    data = rows.slice(h + 1);
    feedRows = data.length;
    const missing = REQUIRED.filter(n => col[n] === -1);
    if (missing.length) feed = { ...feed, ok: false, reason: 'missing_columns: ' + missing.join(', ') };
  }
}
if (feed.ok) {
  const ageH = (now.getTime() - feed.receivedMs) / 3600000;
  const noId = data.filter(r => !String(r[col.id] ?? '').trim()).length;
  const badDate = data.filter(r => !ymd(r[col.entrydate])).length;
  windowStart = data.map(r => ymd(r[col.SDate])).find(Boolean) || null;
  const maxLookback = Math.max(...due.map(v => v.lookback_days || 90), 1);
  if (!Number.isFinite(ageH) || ageH > FEED_MAX_AGE_HOURS) feed = { ...feed, ok: false, reason: `feed_stale (${Number.isFinite(ageH) ? ageH.toFixed(1) + 'h old' : 'no date'})` };
  else if (feedRows === 0) feed = { ...feed, ok: false, reason: 'feed_empty' };
  else if (noId) feed = { ...feed, ok: false, reason: `rows_missing_lead_id (${noId})` };
  else if (badDate) feed = { ...feed, ok: false, reason: `rows_with_bad_entry_date (${badDate})` };
  else if (!windowStart || windowStart > addDays(today, -maxLookback)) feed = { ...feed, ok: false, reason: `feed_window_too_short (starts ${windowStart || '?'}, need ${addDays(today, -maxLookback)} or earlier)` };
  else if (prevRows && feedRows < prevRows * MIN_SIZE_VS_LAST) feed = { ...feed, ok: false, reason: `feed_much_smaller_than_last (${feedRows} vs ${prevRows})` };
}

// ---------- 2. Unmapped sub-sources in the feed (internal summary only) ----------
const unmapped = {};
let blankSource = 0;
if (feed.ok) {
  for (const r of data) {
    const ss = String(r[col.SourceSubDescr] ?? '').trim();
    if (!ss) { blankSource++; continue; }
    if (!mapped.has(norm(ss))) (unmapped[ss] ||= new Set()).add(String(r[col.id]).trim());
  }
  for (const k of Object.keys(unmapped)) unmapped[k] = unmapped[k].size;   // distinct leads per unmapped sub-source
}

// ---------- 3. One report per due vendor ----------
const cell = (r, names) => { for (const n of names) { const i = col[n]; if (i !== undefined && i !== -1) return String(r[i] ?? '').trim(); } return ''; };
const out = [];
for (const v of due) {
  const base = {
    vendor_id: v.vendor_id, vendor_name: v.vendor_name, week_start: v.week_start, scheduled_for: v.scheduled_for,
    dry_run: v.dry_run !== false, lookback_days: v.lookback_days || 90,
    source_file: feed.file || null, source_row_count: feed.ok ? feedRows : null, feed_received_at: feed.received_at || null,
    internal_to: INTERNAL_TO, date: today,
  };
  if (!feed.ok) { out.push({ json: { ...base, status: 'blocked', reason: feed.reason } }); continue; }
  const to = (v.recipients_to || []).filter(Boolean), cc = (v.recipients_cc || []).filter(Boolean);
  if (!base.dry_run && to.length === 0) { out.push({ json: { ...base, status: 'blocked', reason: 'no_recipients (vendor is live but recipients_to is empty)' } }); continue; }
  const subs = new Set((v.lp_sub_sources || []).map(norm));
  const cutoff = addDays(today, -base.lookback_days);
  const mine = data.filter(r => subs.has(norm(r[col.SourceSubDescr])) && ymd(r[col.entrydate]) >= cutoff);
  // Expected: every distinct lead id from this vendor in the window.
  const expected = new Set(mine.map(r => String(r[col.id]).trim()));
  // One row per lead: a current (non-Superseded) row beats a Superseded one, then newest entry, then newest appt, then latest in file.
  const rank = (r, i) => [/^superseded$/i.test(cell(r, ['Category'])) ? 0 : 1, ymd(r[col.entrydate]) || '', ymd(cell(r, ['ApptDate'])) || '', i];
  const better = (a, b) => { for (let k = 0; k < a.length; k++) if (a[k] !== b[k]) return a[k] > b[k]; return false; };
  const best = new Map();
  mine.forEach((r, i) => { const id = String(r[col.id]).trim(); const cur = best.get(id); const rk = rank(r, i); if (!cur || better(rk, cur.rk)) best.set(id, { r, rk }); });
  const finalRows = [...best.values()].map(x => x.r).sort((a, b) => (ymd(b[col.entrydate]) || '').localeCompare(ymd(a[col.entrydate]) || ''));
  // RECONCILE: every expected lead must be in the file exactly once.
  const got = new Set(finalRows.map(r => String(r[col.id]).trim()));
  const missingIds = [...expected].filter(id => !got.has(id));
  if (finalRows.length !== expected.size || missingIds.length || got.size !== finalRows.length) {
    out.push({ json: { ...base, status: 'blocked', reason: `reconcile_mismatch (expected ${expected.size}, built ${finalRows.length}, missing ${missingIds.slice(0, 5).join(',')})` } });
    continue;
  }
  if (finalRows.length === 0) { out.push({ json: { ...base, status: 'empty', lead_count: 0, reason: `no leads from ${[...v.lp_sub_sources].join(', ')} since ${cutoff}` } }); continue; }
  const slug = v.vendor_name.replace(/[^A-Za-z0-9]+/g, '_').replace(/^_|_$/g, '');
  const outName = `Reece_${slug}_Lead_Dispositions_${today}.csv`;
  const csv = toCSV([OUT_COLS.map(c => c[0]), ...finalRows.map(r => OUT_COLS.map(c => {
    const val = cell(r, c[1]);
    return /date/i.test(c[0]) ? (ymd(val) || val) : val;
  }))]);
  const bd = await this.helpers.prepareBinaryData(Buffer.from(csv, 'utf8'), outName, 'text/csv');
  const sendTo = base.dry_run ? INTERNAL_TO : to.join(', ');
  out.push({
    json: {
      ...base, status: 'ok', lead_count: finalRows.length, since: cutoff, out_file: outName,
      to: sendTo, cc: base.dry_run ? '' : cc.join(', '), bcc: base.dry_run ? '' : INTERNAL_TO,
      recipients: base.dry_run ? `DRY RUN -> ${INTERNAL_TO} (would go to: ${to.join(', ') || 'no recipients set'})` : [...to, ...cc].join(', '),
      subject: (base.dry_run ? '[DRY RUN] ' : '') + `Reece Windows & Doors - Weekly Lead Status Report - ${v.vendor_name} - ${today}`,
      body: `Hello,\n\nAttached is your weekly lead status report from Reece Windows & Doors.\n\nIt lists all ${finalRows.length} leads ${v.vendor_name} provided to Reece in the last ${base.lookback_days} days (entered ${cutoff} to ${today}), with each lead's current status as of today.\n\nQuestions: ${INTERNAL_TO}\n\nReece Windows & Doors`,
    },
    binary: { data: bd },
  });
}
// Feed-level info rides on the first item so the summary step can report it.
if (out.length) out[0].json.feed_info = { ok: feed.ok, reason: feed.ok ? null : feed.reason, file: feed.file || null, rows: feedRows, window_start: windowStart, unmapped, blank_source_rows: blankSource };
return out;

// ===== 06 VDR — Summarize & build log rows =====
// Runs after the send branch. Joins each vendor's build result with its Gmail result,
// produces one vdr_send_log row per vendor, and one plain-text summary for Mark.
const built = $('Build vendor reports').all().map(i => i.json);
let sends = [];
try { sends = $('Send vendor report').all().map(i => i.json); } catch (e) { sends = []; }  // no ok items -> node never ran

const okBuilt = built.filter(b => b.status === 'ok');
const execId = String($execution.id ?? '');
const rows = [], lines = [];
let s = 0;
for (const b of built) {
  let status = b.status, reason = b.reason || null;
  if (b.status === 'ok') {
    const g = sends[okBuilt.indexOf(b)];
    const sentOk = g && !g.error && (g.id || (Array.isArray(g.labelIds) && g.labelIds.includes('SENT')));
    status = sentOk ? 'sent' : 'failed';
    if (!sentOk) reason = 'gmail_error: ' + JSON.stringify(g?.error ?? g ?? 'no result').slice(0, 300);
    if (sentOk) s++;
  }
  rows.push({
    vendor_id: b.vendor_id, vendor_name: b.vendor_name, week_start: b.week_start, scheduled_for: b.scheduled_for,
    dry_run: b.dry_run, status, lead_count: b.lead_count ?? null, recipients: b.recipients ?? null,
    out_file: b.out_file ?? null, reason, source_file: b.source_file, source_row_count: b.source_row_count,
    feed_received_at: b.feed_received_at, n8n_execution_id: execId,
  });
  const label = { sent: b.dry_run ? 'SENT (dry run, to Mark only)' : 'SENT', failed: 'FAILED', blocked: 'BLOCKED', empty: 'NO LEADS' }[status];
  lines.push(`- ${b.vendor_name}: ${label}${b.lead_count != null ? ` · ${b.lead_count} leads` : ''}${b.recipients && status === 'sent' ? ` · ${b.recipients}` : ''}${reason ? ` · ${reason}` : ''}`);
}
const fi = built[0]?.feed_info || {};
const count = st => rows.filter(r => r.status === st).length;
const problems = count('failed') + count('blocked');
const allDry = rows.every(r => r.dry_run);
const date = built[0]?.date || '';
const subject = `${allDry ? '[DRY RUN] ' : ''}${problems ? 'ACTION NEEDED - ' : ''}Vendor disposition reports: ${count('sent')} sent, ${count('blocked')} blocked, ${count('failed')} failed, ${count('empty')} no leads (${date})`;
const unm = Object.entries(fi.unmapped || {}).sort((a, b) => b[1] - a[1]);
const body = [
  `Weekly vendor lead status reports - ${date}`, '',
  ...lines, '',
  `Feed: ${fi.file || '-'} · ${fi.rows ?? '-'} rows · window from ${fi.window_start || '-'}${fi.ok === false ? ` · NOT USABLE: ${fi.reason}` : ''}`,
  '',
  unm.length ? `Sub-sources in LP with NO vendor (add them to vdr_vendor_config, or as an inactive row to silence):\n${unm.map(([k, n]) => `  ${k}: ${n} leads`).join('\n')}` : 'Every sub-source in the feed belongs to a vendor.',
  fi.blank_source_rows ? `Leads with a blank sub-source in LP: ${fi.blank_source_rows} rows (cannot be assigned to any vendor).` : '',
  '',
  'What the statuses mean:',
  'BLOCKED = nothing was sent because a check failed. It retries hourly, up to 3 times this week.',
  'FAILED = the email did not go out. It retries hourly, up to 3 times this week.',
  'NO LEADS = the vendor had no leads in the window, so no email was sent.',
  '',
  `n8n execution: ${execId}`,
].filter(l => l !== null).join('\n');
return [{ json: { log_rows: rows, subject, body, problems, internal_to: built[0]?.internal_to } }];
